const body = $json.body ?? $json;
const fields = body.workflowFields ?? body;
const required = ['Role_ID','Created_At','Status','Last_Updated_At','Last_Updated_By_Name','Last_Updated_By_Email','Latest_Comments','Resume_Target_Status'];
for (const field of required) if (typeof fields[field] !== 'string') throw new Error(`Missing server-generated field: ${field}`);
if (fields.Status !== 'Pending HR Discussion') throw new Error('New role requests must start at Pending HR Discussion');
const role = body.role ?? {};
const requiredRoleFields = [['Job_Description', role.jobDescription],['Job_Title', role.jobTitle],['Department', role.department],['Number_Of_Vacancies', role.numberOfVacancies],['Reason_For_Request', role.reasonForRequest],['Target_Hiring_Date', role.targetHiringDate]];
const missingFields = requiredRoleFields.filter(([, value]) => String(value ?? '').trim() === '').map(([name]) => name);
if (missingFields.length) throw new Error(`REQUISITION_INCOMPLETE: ${missingFields.join(', ')}`);
const row = {Request_Type:role.requestType??'',Department:role.department??'',Job_Title:role.jobTitle??'',Number_Of_Vacancies:role.numberOfVacancies??'',Reason_For_Request:role.reasonForRequest??'',Job_Description:role.jobDescription??'',Replacement_Employee:role.replacementEmployee??'',Target_Hiring_Date:role.targetHiringDate??'',HOD_Availability_Dates:role.hodAvailabilityDates??'',HOD_Availability_Times:role.hodAvailabilityTimes??'',Custom_Screening_Question_1:role.customScreeningQuestion1??'',Custom_Screening_Question_2:role.customScreeningQuestion2??'',AI_Screening_Questions:(role.aiGeneratedScreeningQuestions??[]).slice(0,5).join('\n'),Reporting_Manager:role.reportingManager??'',Work_Location:role.workLocation??'',Employment_Type:role.employmentType??'',Job_Responsibilities:role.jobResponsibilities??'',Required_Skills:role.requiredSkills??'',Experience_Required:role.experienceRequired??'',Education_Requirements:role.educationRequirements??'',Preferred_Qualifications:role.preferredQualifications??'',Role_Expectations:role.roleExpectations??'',Salary_Min:role.salaryMin??'',Salary_Max:role.salaryMax??'',Work_Schedule:role.workSchedule??'',Notice_Period_Requirement:role.noticePeriodRequirement??'',Salary_Expectation_Guidance:role.salaryExpectationGuidance??'',Role_ID:fields.Role_ID,Created_At:fields.Created_At,Status:fields.Status,Last_Updated_At:fields.Last_Updated_At,Last_Updated_By_Name:fields.Last_Updated_By_Name,Last_Updated_By_Email:fields.Last_Updated_By_Email,Latest_Comments:fields.Latest_Comments,Resume_Target_Status:fields.Resume_Target_Status,Requester_Name:body.requester?.name??'',Requester_Email:body.requester?.email??'',Requester_Type:body.requester?.type??'',Submitted_By_Name:body.submittedBy?.name??'',Submitted_By_Email:body.submittedBy?.email??'',Submission_ID:body.submissionId??'',Source:body.source??'Role Creation Website'};
return [{json:row}];
